import React, { useState } from "react";
import { Box, AppBar, Toolbar, Typography, Drawer, List, ListItem, ListItemIcon, ListItemText } from "@mui/material";
import { Dashboard as DashboardIcon, HowToVote, BarChart, ExitToApp } from "@mui/icons-material";
import DashboardHome from "./DashboardHome";
import VotingPage from "./VotingPage";
import ResultsPage from "./ResultsPage";

const drawerWidth = 240;

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState("Dashboard");

  // Function to render the appropriate component based on activeTab
  const renderContent = () => {
    switch (activeTab) {
      case "Dashboard":
        return <DashboardHome />;
      case "Vote":
        return <VotingPage />;
      case "Results":
        return <ResultsPage />;
      default:
        return <Typography variant="h4">Logging Out...</Typography>;
    }
  };

  return (
    <Box sx={{ display: "flex", minHeight: "100vh" }}>
      {/* Top Bar */}
      <AppBar position="fixed" sx={{ width: "100%", backgroundColor: "#007bff", zIndex: (theme) => theme.zIndex.drawer + 1 }}>
        <Toolbar>
          <Typography variant="h6" noWrap>
            SRC E-Voting System
          </Typography>
        </Toolbar>
      </AppBar>

      {/* Sidebar Navigation */}
      <Drawer
        variant="permanent"
        sx={{
          width: drawerWidth,
          flexShrink: 0,
          [`& .MuiDrawer-paper`]: { width: drawerWidth, boxSizing: "border-box", backgroundColor: "white", mt: 8, display: "flex", flexDirection: "column", height: "calc(100vh - 64px)", justifyContent: "space-between" },
        }}
      >
        <Box>
          <Toolbar />
          <List>
            {[{ text: "Dashboard", icon: <DashboardIcon /> }, { text: "Vote", icon: <HowToVote /> }, { text: "Results", icon: <BarChart /> }].map(({ text, icon }) => (
              <ListItem
                button
                key={text}
                onClick={() => setActiveTab(text)}
                sx={{ backgroundColor: activeTab === text ? "#007bff" : "transparent", color: activeTab === text ? "white" : "black" }}
              >
                <ListItemIcon sx={{ color: activeTab === text ? "white" : "black" }}>{icon}</ListItemIcon>
                <ListItemText primary={text} />
              </ListItem>
            ))}
          </List>
        </Box>
        <Box>
          <List>
            <ListItem button onClick={() => setActiveTab("Logout")} sx={{ color: "#d32f2f" }}>
              <ListItemIcon sx={{ color: "#d32f2f" }}><ExitToApp /></ListItemIcon>
              <ListItemText primary="Logout" />
            </ListItem>
          </List>
        </Box>
      </Drawer>

      {/* Main Content */}
      <Box sx={{ flexGrow: 1, display: "flex", flexDirection: "column", pt: 8 }}>
        <Box sx={{ flexGrow: 1, p: 3, display: "flex", justifyContent: "center", alignItems: "center", backgroundColor: "rgba(100, 200, 225, 0.3)", minHeight: "100vh" }}>
          {renderContent()}
        </Box>
      </Box>
    </Box>
  );
};

export default Dashboard;
